create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function pg_temp.fails(statement text,expected text,label text) returns void language plpgsql as $$begin begin execute statement; exception when others then if position(expected in sqlerrm)>0 then perform pg_temp.ok(true,label);return;end if;raise;end;raise exception 'Unexpected success: %',label;end $$;
insert into auth.users(id) values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
insert into auth.sessions values('33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111',null);
set role service_role;
select pg_temp.fails($q$select public.issue_memory_identity_request('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','ADULT_IDENTITY')$q$,'VERIFICATION_POLICY_CHANGED','identity issuance defaults closed');
reset role;
update private.memory_identity_policies set enabled=true,revision='LOCAL_TEST',provider='synthetic',channel='test',daily_limit=2;
set role authenticated;
select pg_temp.fails($q$select public.issue_memory_identity_request('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','ADULT_IDENTITY')$q$,'permission denied','client cannot issue trusted requests');
select pg_temp.fails($q$select public.complete_memory_identity_request('{}')$q$,'permission denied','client cannot complete trusted requests');
select pg_temp.fails('select * from private.memory_identity_requests','permission denied','client cannot read identity ledger');
select pg_temp.fails($q$select public.get_memory_identity_request('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','ADULT_IDENTITY','44444444-4444-4444-8444-444444444444')$q$,'permission denied','client cannot read service request DTO');
select pg_temp.fails($q$select public.get_memory_identity_policy('ADULT_IDENTITY')$q$,'permission denied','client cannot read internal provider policy');
set role service_role;
select pg_temp.fails($q$select public.issue_memory_identity_request('22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333','ADULT_IDENTITY')$q$,'AUTH_REQUIRED','session cannot bind to another account');
select set_config('test.request',public.issue_memory_identity_request('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','ADULT_IDENTITY')::text,false);
select pg_temp.ok(public.issue_memory_identity_request('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','ADULT_IDENTITY')->>'id'=current_setting('test.request')::jsonb->>'id','issuance retry reuses live request');
select set_config('test.expected',((current_setting('test.request')::jsonb-'id'-'status')||jsonb_build_object('requestId',current_setting('test.request')::jsonb->>'id'))::text,false);
select pg_temp.fails($q$select public.complete_memory_identity_request(jsonb_set(current_setting('test.expected')::jsonb,'{purpose}','"GUARDIAN_IDENTITY"'))$q$,'VERIFICATION_REQUEST_CHANGED','wrong purpose cannot consume request');
select pg_temp.ok(public.complete_memory_identity_request(current_setting('test.expected')::jsonb)->>'status'='RECORDED','exact server evidence consumes request');
select pg_temp.fails($q$select public.complete_memory_identity_request(current_setting('test.expected')::jsonb)$q$,'VERIFICATION_REQUEST_CHANGED','replay cannot record again');
select set_config('test.request',public.issue_memory_identity_request('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','ADULT_IDENTITY')::text,false);
select set_config('test.expected',((current_setting('test.request')::jsonb-'id'-'status')||jsonb_build_object('requestId',current_setting('test.request')::jsonb->>'id'))::text,false);
reset role;
begin;
update private.memory_identity_policies set revision='NEW';
set local role service_role;
select pg_temp.fails($q$select public.complete_memory_identity_request(current_setting('test.expected')::jsonb)$q$,'VERIFICATION_POLICY_CHANGED','changed policy rejects pending evidence');
rollback;
begin;
delete from auth.sessions;
set local role service_role;
select pg_temp.fails($q$select public.complete_memory_identity_request(current_setting('test.expected')::jsonb)$q$,'AUTH_REQUIRED','logout rejects outstanding evidence');
rollback;
begin;
update private.memory_identity_requests set expires_at=clock_timestamp()-interval '1 second' where id=(current_setting('test.request')::jsonb->>'id')::uuid;
select set_config('test.expired',((private.memory_identity_request_dto(r)-'id'-'status')||jsonb_build_object('requestId',r.id))::text,true) from private.memory_identity_requests r where id=(current_setting('test.request')::jsonb->>'id')::uuid;
set local role service_role;
select pg_temp.fails($q$select public.complete_memory_identity_request(current_setting('test.expired')::jsonb)$q$,'VERIFICATION_EXPIRED','expired request cannot record');
rollback;
set role service_role;
select pg_temp.fails($q$select public.issue_memory_identity_request('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','GUARDIAN_IDENTITY')$q$,'VERIFICATION_RATE_LIMITED','request quota covers purposes together');
reset role;
select pg_temp.ok((select count(*)=1 from private.memory_identity_requests where status='RECORDED'),'only successful completion recorded evidence');
